python3 - <<'PY'
import json, os, re
data_dir = '/app/data'
def load(name):
    with open(os.path.join(data_dir, name)) as f:
        return json.load(f)
topology = load('topology.json')
relationships = load('relationships.json')
prefs = load('preferences.json')
route = load('route.json')
route_events = load('route_events.json')
solutions = load('possible_solutions.json')
# ---- Step 1: sanity checks (lightweight) ----
ases=set()
for c in topology.get('connections',[]):
    ases.add(int(c['from'])); ases.add(int(c['to']))
for r in relationships:
    ases.add(int(r['from'])); ases.add(int(r['to']))
# Build relationship map (directed)
rel = {(int(r['from']), int(r['to'])): r['type'] for r in relationships}
# Validate symmetry for provider/customer and peer
for (a,b),t in list(rel.items()):
    if t=='provider':
        if rel.get((b,a))!='customer':
            raise ValueError(f"Relationship symmetry failed: {a}->{b} provider but {b}->{a} not customer")
    if t=='customer':
        if rel.get((b,a))!='provider':
            raise ValueError(f"Relationship symmetry failed: {a}->{b} customer but {b}->{a} not provider")
    if t=='peer':
        if rel.get((b,a))!='peer':
            raise ValueError(f"Relationship symmetry failed: {a}->{b} peer but {b}->{a} not peer")
# ---- Step 2: detect oscillation (preference cycle) ----
pref_next = {int(k): int(v['prefer_via']) for k,v in prefs.items() if isinstance(v, dict) and 'prefer_via' in v}
def find_cycle(pref):
    visited=set()
    for start in pref:
        if start in visited:
            continue
        path=[]
        seen_index={}
        cur=start
        while cur in pref:
            if cur in seen_index:
                cyc = path[seen_index[cur]:]
                return cyc
            if cur in visited:
                break
            seen_index[cur]=len(path)
            path.append(cur)
            cur=pref[cur]
        visited.update(path)
    return None
cycle = find_cycle(pref_next)
osc_detected = cycle is not None
osc_cycle = cycle or []
affected_ases = sorted(set(osc_cycle))
# ---- Step 3: detect route leaks from route_events evidence ----
# Valley-free violation: learned from provider/peer and exported to peer/provider.
route_leaks=[]
for ev in route_events:
    src_type=ev.get('source_type')
    dst_type=ev.get('destination_type')
    if src_type in ('provider','peer') and dst_type in ('provider','peer'):
        route_leaks.append({
            'leaker_as': int(ev['advertiser_asn']),
            'source_as': int(ev['source_asn']),
            'destination_as': int(ev['destination_asn']),
            'source_type': src_type,
            'destination_type': dst_type,
        })
route_leak_detected = len(route_leaks)>0
# ---- Step 4: evaluate solutions ----
def resolves_oscillation(text: str) -> bool:
    t=text.lower().strip()
    # Prohibited / non-fixes
    if 'disable hub peering' in t or 'restart bgp' in t or t.startswith('wait for'):
        return False
    if 'keepalive' in t or 'holdtime' in t or 'dampening' in t or 'maximum-prefix' in t or 'ecmp' in t:
        return False
    # Direct preference change: breaks the pref graph edge(s)
    if 'update routing preference' in t and 'stop preferring routes via hub2' in t:
        return True
    if 'set route preference hierarchy' in t:
        return True
    # Break one leg of the cycle by filtering peer-learned routes
    if 'filter out routes learned from hub2' in t:
        return True
    if 'filter out routes learned from hub1' in t:
        return True
    # Other solutions listed do not explicitly break the preference cycle
    return False
def resolves_route_leak(text: str) -> bool:
    t=text.lower().strip()
    # Prohibited / non-fixes
    if 'disable hub peering' in t or 'restart bgp' in t or t.startswith('wait for'):
        return False
    if 'keepalive' in t or 'holdtime' in t or 'dampening' in t or 'maximum-prefix' in t or 'ecmp' in t:
        return False
    # Must stop advertising provider (Virtual WAN) routes to peer hub.
    if 'block announcing provider routes' in t and 'to peer' in t:
        return True
    if 'enforce no-export' in t and 'provider routes' in t and 'peer' in t:
        return True
    if 'export policy' in t and 'block announcing provider routes' in t:
        return True
    # Ingress filtering / RPKI / accept filters / UDR / routing intent don't stop the advertisement itself.
    return False
solution_results = {
    s: {
        'oscillation_resolved': bool(resolves_oscillation(s)) if osc_detected else False,
        'route_leak_resolved': bool(resolves_route_leak(s)) if route_leak_detected else False,
    }
    for s in solutions
}
report = {
    'oscillation_detected': bool(osc_detected),
    'oscillation_cycle': osc_cycle,
    'affected_ases': affected_ases,
    'route_leak_detected': bool(route_leak_detected),
    'route_leaks': route_leaks,
    'solution_results': solution_results,
}
out_dir='/app/output'
os.makedirs(out_dir, exist_ok=True)
out_path=os.path.join(out_dir,'oscillation_report.json')
with open(out_path,'w') as f:
    json.dump(report, f, indent=2, sort_keys=False)
print(out_path)
